    GROUP BY ?award
  }
  {
    SELECT ?award (COUNT(DISTINCT ?femaleRecipient) AS ?femaleCount) WHERE {
      ?femaleRecipient wdt:P166 ?award .
      ?femaleRecipient wdt:P21 wd:Q6581072 .
