  }
  UNION
  {
    ?person wdt:P2003 ?account1 .
    ?person wdt:P2003 ?account2 .
  }
  UNION
  {
    ?person wdt:P2013 ?account1 .
    ?person wdt:P2013 ?account2 .
  }
  UNION
  {
    ?person wdt:P7085 ?account1 .
    ?person wdt:P7085 ?account2 .
  }

  FILTER(?account1 != ?account2)
  FILTER(LCASE(STR(?account1)) = LCASE(STR(?account2)))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

