SELECT ?occupation ?occupationLabel ?maleCount ?femaleCount (ABS(?maleCount - ?femaleCount) AS ?imbalance) WHERE {
  {
    SELECT ?occupation (COUNT(?male) AS ?maleCount) WHERE {
      ?male wdt:P106 ?occupation .
      ?male wdt:P21 wd:Q6581097 .
      ?male wdt:P27 wd:Q30 .
    }
    GROUP BY ?occupation
  }
  {
    SELECT ?occupation (COUNT(?female) AS ?femaleCount) WHERE {
      ?female wdt:P106 ?occupation .
      ?female wdt:P21 wd:Q6581072 .
      ?female wdt:P27 wd:Q30 .
    }
    GROUP BY ?occupation
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?imbalance)
LIMIT 20

