  ?facility wdt:P625 ?coord .
  VALUES ?type {
    wd:Q16917
    wd:Q1774898
    wd:Q13107184
    wd:Q86206293
  }
  BIND(
    IF(?type = wd:Q16917, "FF0000",
    IF(?type = wd:Q1774898, "00FF00",
    IF(?type = wd:Q13107184, "0000FF",
    "FFFF00"))) AS ?rgb
