SELECT ?decade ?placeLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P166 ?award .
  ?award wdt:P31/wdt:P279* wd:Q7191 .
  ?person wdt:P19 ?place .
  ?person wdt:P569 ?dob .
